class Father:
    def skill1(self):
        print("Father's skill: Gardening")
class Mother:
    def skill2(self):
        print("Mother's skill: Cooking")

# Derived class inheriting from two base classes
class Child(Father, Mother):
    def own_skill(self):
        print("Child's skill: Coding")
# Creating an instance of Child
c = Child()
c.skill1()                  # Accessing Father's method
c.skill2()                  # Accessing Mother's method
c.own_skill()               # Accessing its own method
